# R's "data are essentially constant" boundary for gaply_core's three
# analysis t-tests (Research OS, Phase 8D-1b, decision 259).
#
# Run as: /usr/local/bin/Rscript make_essentially_constant.R
# It writes, beside itself: one data_<case>.csv per case, r_outcomes.csv (what
# R's t.test did with each case) and cells_bits.csv (the IEEE 754 bits of
# every number R read back). Every file it writes names this command in its
# header.
#
# R is the test oracle here and nothing more: Gaply's rule is its own code.
# R's rule is in t.test.default, src/library/stats/R/t.test.R (trunk, lines
# 62-64 and 94, read 26 Oct 2026): it stops when the standard error is below
# 10 * .Machine$double.eps * |mean| (one-sample and paired, the mean of the
# differences) or * max(|mean x|, |mean y|) (two-sample).
#
# Every cell is written as text with sprintf("%.17g"), which names its double
# exactly; write.csv's defaults keep 15 digits and would turn
# 1.0000000000000002 into 1. Each file is READ BACK, and R's outcome is of the
# values it read. R's reader misreads some 17-digit cells (1000.0000000000001
# reads as 1000): a case where R read back a double other than the one it
# wrote is not an R case. It is left out of r_outcomes.csv and named in its
# header, and kept, if at all, as a Rust-only test.
#
# Every case is at least ten times either side of R's threshold, so that
# Gaply's and R's standard errors, which may differ by a few ulps, fall on the
# same side; the script stops if one is not, or if a standard error is 0.
# Values stay between 1e-30 and 1e30.

PROVENANCE <- "/usr/local/bin/Rscript make_essentially_constant.R"
args <- commandArgs(trailingOnly = FALSE)
here <- dirname(normalizePath(sub("^--file=", "", args[grep("^--file=", args)])))

header <- function(what) c(
  sprintf("# %s for gaply_core's essentially-constant rule (Research OS, Phase 8D-1b).", what),
  sprintf("# Generated by %s (do not edit by hand).", PROVENANCE),
  sprintf("# %s, %s.", R.version.string, R.version$arch)
)
f17 <- function(x) sprintf("%.17g", x)
bits <- function(x) paste(as.character(writeBin(x, raw(), size = 8, endian = "big")), collapse = "")
EPS10 <- 10 * .Machine$double.eps

outcomes <- list()
cells <- list()
rust_only <- character(0)

# Writes the case's file, reads it back, and returns the columns R read, or
# NULL when R read back a double other than the one written.
roundtrip <- function(case, df) {
  name <- sprintf("data_%s.csv", case)
  path <- file.path(here, name)
  text <- df
  for (col in names(df)) if (is.numeric(df[[col]])) text[[col]] <- f17(df[[col]])
  lines <- c(header(sprintf("Data of case %s", case)), paste(names(df), collapse = ","),
             apply(as.matrix(text), 1, paste, collapse = ","))
  writeLines(lines, path, useBytes = TRUE)
  back <- read.csv(path, comment.char = "#", stringsAsFactors = FALSE,
                   colClasses = ifelse(sapply(df, is.numeric), "numeric", "character"))
  same <- TRUE
  for (col in names(df)) {
    if (!is.numeric(df[[col]])) next
    for (i in seq_along(df[[col]])) {
      if (bits(back[[col]][i]) != bits(df[[col]][i])) same <- FALSE
      cells[[length(cells) + 1]] <<- data.frame(data = name, column = col, row = i,
                                                bits = bits(back[[col]][i]))
    }
  }
  if (!same) {
    rust_only <<- c(rust_only, case)
    return(NULL)
  }
  back
}

# R's outcome: "stopped" on its "essentially constant" error, "computed"
# otherwise; any other error stops this script.
attempt <- function(case, expr) {
  tryCatch({ force(expr); "computed" }, error = function(e) {
    if (grepl("essentially constant", conditionMessage(e))) "stopped"
    else stop(sprintf("%s: R refused otherwise: %s", case, conditionMessage(e)))
  })
}

record <- function(case, method, variant, test_value, outcome, se, threshold) {
  if (!(se > 0)) stop(sprintf("%s %s: a standard error of %s", case, variant, f17(se)))
  ratio <- se / threshold
  if (ratio > 0.1 && ratio < 10) {
    stop(sprintf("%s %s: se / threshold = %.3g, within ten times", case, variant, ratio))
  }
  if ((outcome == "stopped") != (ratio < 1)) {
    stop(sprintf("%s %s: R %s at ratio %.3g", case, variant, outcome, ratio))
  }
  outcomes[[length(outcomes) + 1]] <<- data.frame(
    case = case, method = method, variant = variant, test_value = test_value,
    r_outcome = outcome, r_se = f17(se), r_threshold = f17(threshold))
}

one_case <- function(case, x, test_value = 0) {
  d <- roundtrip(case, data.frame(x = x))
  if (is.null(d)) return(invisible())
  x <- d$x
  se <- sqrt(var(x) / length(x)) # line 62's standard error
  outcome <- attempt(case, t.test(x, mu = test_value))
  record(case, "one_sample", "", f17(test_value), outcome, se, EPS10 * abs(mean(x)))
}

paired_case <- function(case, a, b) {
  d <- roundtrip(case, data.frame(a = a, b = b))
  if (is.null(d)) return(invisible())
  diffs <- d$a - d$b # line 53's x - y
  se <- sqrt(var(diffs) / length(diffs))
  outcome <- attempt(case, t.test(d$a, d$b, paired = TRUE))
  record(case, "paired", "", "", outcome, se, EPS10 * abs(mean(diffs)))
}

independent_case <- function(case, ya, yb) {
  d <- roundtrip(case, data.frame(y = c(ya, yb), g = c(rep("a", length(ya)), rep("b", length(yb)))))
  if (is.null(d)) return(invisible())
  x <- d$y[d$g == "a"]
  y <- d$y[d$g == "b"]
  nx <- length(x); ny <- length(y)
  vx <- var(x); vy <- var(y)
  threshold <- EPS10 * max(abs(mean(x)), abs(mean(y))) # line 94's scale
  v <- ((nx - 1) * vx + (ny - 1) * vy) / (nx + ny - 2) # lines 82-87
  record(case, "independent", "student", "",
         attempt(case, t.test(x, y, var.equal = TRUE)), sqrt(v * (1 / nx + 1 / ny)), threshold)
  record(case, "independent", "welch", "",
         attempt(case, t.test(x, y, var.equal = FALSE)), sqrt(vx / nx + vy / ny), threshold)
}

# ---- one-sample: scale |mean| --------------------------------------------
# Below: a spread of one ulp.
one_case("one_ulp_0_3", as.numeric(c("0.3", "0.30000000000000004", "0.3", "0.3")))
one_case("one_ulp_1e10", 1e10 + c(0, 2^-19, 0), test_value = 1e10)
one_case("one_ulp_neg7_5", -7.5 + c(0, -2^-50, 2^-50, 0))
one_case("one_ulp_neg3", -3 + c(0, 2^-51, 0, -2^-51))
# Above.
one_case("one_above_0_3", 0.3 + c(0, 1, 2, 0) * 1e-13)
one_case("one_above_1e6", 1e6 + c(0, 1, 2, 3) * 1e-7, test_value = 1e6)
one_case("one_above_neg50", -50 + c(0, 3, 1, 2) * 1e-11, test_value = -50)

# ---- independent: scale max(|mean 1|, |mean 2|), Student and Welch ----------
# Below.
independent_case("ind_ulp_1_2", 1 + c(0, 2^-52, 0), 2 + c(0, 2^-51, 0))
independent_case("ind_ulp_neg3_5", -3 + c(0, 2^-51, 0, -2^-51), 5 + c(0, 2^-50, 0))
independent_case("ind_ulp_1e8", 1e8 + c(0, 2^-26, 0), 1e8 + 1 + c(0, 0, 2^-26))
independent_case("ind_ulp_16_40", 16 + c(0, 2^-48, 0), 40 + c(0, 0, 2^-47))
# Above.
independent_case("ind_above_1_2", 1 + c(0, 1, 2) * 1e-13, 2 + c(0, 1, 2) * 1e-13)
independent_case("ind_above_neg3_5", -3 + c(0, 1, 2) * 1e-12, 5 + c(0, 2, 1) * 1e-12)
independent_case("ind_above_1e8", 1e8 + c(0, 1, 2) * 1e-5, 1e8 + 1 + c(0, 1, 2) * 1e-5)

# ---- paired: R's scale |mean of the differences| ----------------------------
# R stops: the second column is the first plus or minus a constant, and the
# differences miss it by an ulp on some rows. (A constant whose sum is exact
# on every row, such as 5 here, gives differences exactly equal: a standard
# error of 0, which is the exact-0 code's case, not this rule's.)
a <- c(5.123, 4.871, 6.042, 3.987, 5.555)
paired_case("pair_minus_two", a, as.numeric(c("3.123", "2.871", "4.042", "1.987", "3.555")))
a <- c(1.234, 0.871, 1.502, 0.663, 1.118, 1.377)
paired_case("pair_plus_2_7", a, a + 2.7)
paired_case("pair_plus_2_9", a, a + 2.9)
a <- -c(1.234, 1.871, 1.502, 1.663, 1.118)
paired_case("pair_neg_minus_4_3", a, a - 4.3)
# R computes, where Gaply's own scale (the mean of |first| and of |second|)
# refuses: every pair differs by the same small amount, and the rounding in
# first minus second is far above 10 * eps * that amount. (pair_1e6_minus_1_1
# was meant as one more; its differences are exactly equal in memory, and R's
# reader, misreading a cell, made the spread. It is Rust-only.)
paired_case("pair_tenth", c(100.2, 101.7, 99.3, 102.4, 98.6),
            c(100.1, 101.6, 99.2, 102.3, 98.5))
a <- 1e6 + c(0.13, 0.71, 0.37, 0.93, 0.59)
paired_case("pair_1e6_minus_1_1", a, a - 1.1)
paired_case("pair_300_fifth", c(300.3, 301.8, 299.4, 302.6, 298.7),
            c(300.1, 301.6, 299.2, 302.4, 298.5))
paired_case("pair_20_hundredth", c(20.31, 21.84, 19.42, 22.65, 18.77),
            c(20.30, 21.83, 19.41, 22.64, 18.76))
# R and Gaply both compute.
paired_case("pair_above_both", c(100.2, 101.7, 99.3, 102.4, 98.6),
            as.numeric(c("100.1", "101.59999999999", "99.19999999998", "102.29999999997", "98.49999999996")))
set.seed(20261026)
a <- round(rnorm(8, 20, 2), 2)
paired_case("pair_spread", a, round(a + rnorm(8, 0.5, 0.3), 2))

# ---- files ------------------------------------------------------------------
out <- do.call(rbind, outcomes)
con <- file(file.path(here, "r_outcomes.csv"), "w")
writeLines(c(header("What R's t.test did with each case"),
             sprintf("# Rust-only (R read back a double other than the one written): %s",
                     if (length(rust_only)) paste(rust_only, collapse = " ") else "none")), con)
write.csv(out, con, row.names = FALSE, quote = FALSE)
close(con)
cb <- do.call(rbind, cells)
con <- file(file.path(here, "cells_bits.csv"), "w")
writeLines(header("The IEEE 754 bits of every number R read back"), con)
write.csv(cb, con, row.names = FALSE, quote = FALSE)
close(con)
cat(sprintf("%d outcomes (%d stopped), %d cells, Rust-only: %s\n", nrow(out),
            sum(out$r_outcome == "stopped"), nrow(cb),
            if (length(rust_only)) paste(rust_only, collapse = " ") else "none"))
